{"targets":[{"type":"code","code":"var A = 21, C = 15;
function say(m) { try { log.info('SPIKE ' + m); } catch (e) {} }

// (a) запись напрямую из блочного сценария
var b0 = Hub.getCharacteristicValue(A, C);
say('[block-direct] before=' + b0);
Hub.setCharacteristicValue(A, C, !b0);
say('[block-direct] AFTER-SET=' + Hub.getCharacteristicValue(A, C) + ' EXPECTED=' + !b0);
Hub.setCharacteristicValue(A, C, b0);

// (b) через функцию, объявленную в глобальном сценарии - случай TGActions
try { global.SpikeHubAccess.probe('[block-calls-global]'); }
catch (e) { say('[block-calls-global] THREW ' + e); }

// (c) таймер, заведённый внутри глобальной функции - случай polling
try { global.SpikeHubAccess.later('[global-timer]'); }
catch (e) { say('[global-timer] THREW ' + e); }"}]}
